  // Filter flights based on selected segments, classes, direct filter, and sources
  const filterFlights = (flights) => {
    console.log(`Filtering ${flights.length} flights`);

    // Clone flights to avoid modifying the original array
    let filteredFlights = [...flights];

    // If there are no flights to filter, return empty array
    if (!filteredFlights || filteredFlights.length === 0) {
      console.log('No flights to filter, returning empty array');
      return [];
    }

    // First, let's get routes and their scopes
    const routeScopes = {};
    filteredFlights.forEach(flight => {
      if (flight.rawData) {
        const origin = flight.rawData.originAirport;
        const destination = flight.rawData.destinationAirport;
        const routeKey = `${origin}-${destination}`;

        if (!routeScopes[routeKey]) {
          routeScopes[routeKey] = {
            isInGroupFilterScope: false,
            isInSegmentFilterScope: false,
            inGroupFilters: [],
            inSegmentFilters: []
          };
        }

        // Check if this route is in scope for any group filter
        filters.groups.forEach(filter => {
          const originMatches = filter.origins.includes(origin);
          const destMatches = filter.destinations.includes(destination);
          if (originMatches && destMatches) {
            routeScopes[routeKey].isInGroupFilterScope = true;
            routeScopes[routeKey].inGroupFilters.push(filter.id);
          }
        });

        // Check if this route is in scope for any segment filter
        filters.segments.forEach(filter => {
          if (filter.segments.includes(routeKey)) {
            routeScopes[routeKey].isInSegmentFilterScope = true;
            routeScopes[routeKey].inSegmentFilters.push(filter.id);
          }
        });
      }
    });

    console.log('Route scopes detected:', routeScopes);

    // Apply global filters (apply to all flights)
    if (filters.direct && filters.direct.enabled) {
      console.log('Applying direct filter');
      filteredFlights = filteredFlights.filter(flight => {
        return filters.direct.value ? flight.direct : true;
      });
      console.log(`After direct filter: ${filteredFlights.length} flights`);
    }

    if (filters.source && filters.source.enabled) {
      console.log('Applying source filter');
      filteredFlights = filteredFlights.filter(flight => {
        const sourceMatches = filters.source.sources.includes(flight.source);
        return filters.source.mode === 'include' ? sourceMatches : !sourceMatches;
      });
      console.log(`After source filter: ${filteredFlights.length} flights`);
    }

    if (filters.airlines && filters.airlines.enabled) {
      console.log('Applying airlines filter');
      filteredFlights = filteredFlights.filter(flight => {
        // Skip if flight has no airlines
        if (!flight.airlines) return filters.airlines.mode === 'exclude';

        const flightAirlines = flight.airlines.split(',').map(a => a.trim());
        const airlineMatches = flightAirlines.some(airline => filters.airlines.airlines.includes(airline));
        return filters.airlines.mode === 'include' ? airlineMatches : !airlineMatches;
      });
      console.log(`After airlines filter: ${filteredFlights.length} flights`);
    }

    if (filters.points && filters.points.enabled) {
      console.log('Applying points filter');
      filteredFlights = filteredFlights.filter(flight => {
        if (!flight.mileageCost) return false;
        return flight.mileageCost >= filters.points.min && flight.mileageCost <= filters.points.max;
      });
      console.log(`After points filter: ${filteredFlights.length} flights`);
    }

    // Apply group-based filters (only for flights in scope for group filters)
    filteredFlights = filteredFlights.filter(flight => {
      if (!flight.rawData) return true;

      const origin = flight.rawData.originAirport;
      const destination = flight.rawData.destinationAirport;
      const routeKey = `${origin}-${destination}`;
      const routeScope = routeScopes[routeKey];

      // If route is not in any filter scope, keep it
      if (!routeScope) return true;

      // If route is not in the scope of any group or segment filter, keep it
      if (!routeScope.isInGroupFilterScope && !routeScope.isInSegmentFilterScope) {
        return true;
      }

      let keepFlight = true;

      // Check against group filters if in scope
      if (routeScope.isInGroupFilterScope) {
        console.log(`Checking flight ${routeKey} against group filters: ${routeScope.inGroupFilters.join(', ')}`);

        // For each group filter that this flight is in scope for, check if it passes
        routeScope.inGroupFilters.forEach(filterId => {
          const filter = filters.groups.find(f => f.id === filterId);
          if (!filter) return;

          // Apply direct filter for group
          if (filter.direct && filter.direct.enabled) {
            if (filter.direct.value && !flight.direct) {
              console.log(`Flight ${routeKey} failed group direct filter ${filterId}`);
              keepFlight = false;
            }
          }

          // Apply source filter for group
          if (filter.source && filter.source.enabled) {
            const sourceMatches = filter.source.sources.includes(flight.source);
            if ((filter.source.mode === 'include' && !sourceMatches) || 
                (filter.source.mode === 'exclude' && sourceMatches)) {
              console.log(`Flight ${routeKey} failed group source filter ${filterId}`);
              keepFlight = false;
            }
          }

          // Apply airlines filter for group
          if (filter.airlines && filter.airlines.enabled) {
            if (!flight.airlines) {
              if (filter.airlines.mode === 'include') {
                console.log(`Flight ${routeKey} failed group airlines filter ${filterId} (no airlines)`);
                keepFlight = false;
              }
            } else {
              const flightAirlines = flight.airlines.split(',').map(a => a.trim());
              const airlineMatches = flightAirlines.some(airline => filter.airlines.airlines.includes(airline));
              if ((filter.airlines.mode === 'include' && !airlineMatches) || 
                  (filter.airlines.mode === 'exclude' && airlineMatches)) {
                console.log(`Flight ${routeKey} failed group airlines filter ${filterId}`);
                keepFlight = false;
              }
            }
          }

          // Apply points filter for group
          if (filter.points && filter.points.enabled) {
            if (!flight.mileageCost || 
                flight.mileageCost < filter.points.min || 
                flight.mileageCost > filter.points.max) {
              console.log(`Flight ${routeKey} failed group points filter ${filterId}`);
              keepFlight = false;
            }
          }
        });
      }

      // Check against segment filters if in scope
      if (routeScope.isInSegmentFilterScope) {
        console.log(`Checking flight ${routeKey} against segment filters: ${routeScope.inSegmentFilters.join(', ')}`);

        // For each segment filter that this flight is in scope for, check if it passes
        routeScope.inSegmentFilters.forEach(filterId => {
          const filter = filters.segments.find(f => f.id === filterId);
          if (!filter) return;

          // Apply direct filter for segment
          if (filter.direct && filter.direct.enabled) {
            if (filter.direct.value && !flight.direct) {
              console.log(`Flight ${routeKey} failed segment direct filter ${filterId}`);
              keepFlight = false;
            }
          }

          // Apply source filter for segment
          if (filter.source && filter.source.enabled) {
            const sourceMatches = filter.source.sources.includes(flight.source);
            if ((filter.source.mode === 'include' && !sourceMatches) || 
                (filter.source.mode === 'exclude' && sourceMatches)) {
              console.log(`Flight ${routeKey} failed segment source filter ${filterId}`);
              keepFlight = false;
