            } else {
              const flightAirlines = flight.airlines.split(',').map(a => a.trim());
              const airlineMatches = flightAirlines.some(airline => filter.airlines.airlines.includes(airline));
              if ((filter.airlines.mode === 'include' && !airlineMatches) || 
                  (filter.airlines.mode === 'exclude' && airlineMatches)) {
                console.log(`Flight ${routeKey} failed segment airlines filter ${filterId}`);
                keepFlight = false;
              }
            }
          }

          // Apply points filter for segment
          if (filter.points && filter.points.enabled) {
            if (!flight.mileageCost || 
