                    {showPagination && (
                      <div 
                        style={{
                          display: 'flex',
                          justifyContent: 'space-between',
                          alignItems: 'center',
                          marginTop: '8px',
                          fontSize: '11px',
                          color: '#555',
                          borderTop: '1px solid #f0f0f0',
                          paddingTop: '6px'
                        }}
                        onClick={(e) => e.stopPropagation()} // Prevent date selection when clicking pagination
                      >
                        <button
                          disabled={currentPage === 0}
                          onClick={(e) => {
                            e.stopPropagation();
                            handlePageChange(dateString, 'prev', e);
                          }}
                          style={{
                            padding: '2px 6px',
                            backgroundColor: 'transparent',
                            border: '1px solid #d9d9d9',
                            borderRadius: '4px',
                            cursor: currentPage === 0 ? 'not-allowed' : 'pointer',
                            color: currentPage === 0 ? '#bbb' : '#555',
                            transition: 'all 0.2s',
                            fontSize: '10px'
                          }}
                        >
                          &lt;
                        </button>

                        <span style={{ fontSize: '10px' }}>{`${currentPage + 1} / ${totalPages}`}</span>

                        <button
                          disabled={currentPage === totalPages - 1}
                          onClick={(e) => {
                            e.stopPropagation();
                            handlePageChange(dateString, 'next', e);
                          }}
                          style={{
                            padding: '2px 6px',
                            backgroundColor: 'transparent',
                            border: '1px solid #d9d9d9',
                            borderRadius: '4px',
                            cursor: currentPage === totalPages - 1 ? 'not-allowed' : 'pointer',
                            color: currentPage === totalPages - 1 ? '#bbb' : '#555',
                            transition: 'all 0.2s',
                            fontSize: '10px'
                          }}
                        >
                          &gt;
                        </button>
                      </div>
                    )}
                  </>
                ) : (
                  <div style={{ 
                    textAlign: 'center', 
                    color: '#999', 
                    fontSize: '12px',
                    marginTop: '32px',
                    fontFamily: 'Menlo, monospace'
                  }}>
                    No flights
                  </div>
                )}
              </div>
            );
          })}
        </div>

        {/* Error message */}
        {error && (
          <div style={{ 
            color: '#ff4d4f', 
            marginTop: '16px',
            textAlign: 'center' 
          }}>
            {error}
          </div>
        )}
      </div>
    </div>
  );
};

export default NormalFlightAvailabilityCalendar;
